package io.ecosync.chat;
import java.util.*;
import java.nio.file.*;
import org.springframework.stereotype.Component;
/** Explicit operator verification, bound to exact tenant/connector/entity/revision/fingerprint. No name inference. */
@Component
public class ChatBindings {
 private final List<Map<String,Object>> entries;
 @SuppressWarnings("unchecked") public ChatBindings(ChatSettings settings){try{if(settings.bindings().isEmpty()){entries=List.of();return;}byte[] bytes=Files.readAllBytes(Path.of(settings.bindings()));if(bytes.length>262144)throw new IllegalArgumentException();var root=ChatData.object(new String(bytes,java.nio.charset.StandardCharsets.UTF_8),262144);ChatData.keys(root,Set.of("version","bindings"));if(!"1.0.0".equals(root.get("version"))||!(root.get("bindings") instanceof List<?> l)||l.size()>64)throw new IllegalArgumentException();entries=(List<Map<String,Object>>)(List<?>)List.copyOf(l);}catch(Exception e){throw new IllegalStateException("Invalid explicit chat source bindings");}}
 public Set<String> identifiers(UUID org,ChatCapabilities.Capability cap,Object data){var result=new HashSet<String>();if(identity(org,cap).isEmpty())return result;for(var e:entries)if(org.toString().equals(e.get("organization"))&&cap.kind().equals(e.get("kind"))&&cap.connector().toString().equals(e.get("connector"))&&cap.entity().toString().equals(e.get("entity"))&&cap.fingerprint().equals(e.get("fingerprint"))&&e.get("revision") instanceof Number n&&n.longValue()==cap.revision()){Object raw=e.get("identifierPaths");if(!(raw instanceof List<?> paths)||paths.size()>8)return Set.of();for(Object path:paths){if(!(path instanceof String text)||text.length()>256||!text.startsWith("/"))throw new ChatFailure("CHAT_BINDING_INVALID");collect(data,text.substring(1).split("/",-1),0,result);}}return result;}
 private static void collect(Object value,String[] parts,int at,Set<String> result){if(at>12)throw new ChatFailure("CHAT_BINDING_INVALID");if(at==parts.length){if(value instanceof String||value instanceof Number)result.add(value.toString());return;}String key=parts[at].replace("~1","/").replace("~0","~");if(key.equals("*")&&value instanceof List<?> list){for(Object item:list)collect(item,parts,at+1,result);}else if(value instanceof Map<?,?> map&&map.containsKey(key))collect(map.get(key),parts,at+1,result);else if(value instanceof List<?> list&&key.matches("0|[1-9][0-9]{0,2}")&&Integer.parseInt(key)<list.size())collect(list.get(Integer.parseInt(key)),parts,at+1,result);}
 @SuppressWarnings("unchecked") public Map<String,String> measure(UUID org,ChatCapabilities.Capability cap,String pointer,Object data){if(identity(org,cap).isEmpty())throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");int slash=pointer.lastIndexOf('/');if(slash<0)throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");String field=pointer.substring(slash+1).replace("~1","/").replace("~0","~");Object parent=ChatData.pointer(data,pointer.substring(0,slash));if(!(parent instanceof Map<?,?> row))throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");for(var e:entries)if(org.toString().equals(e.get("organization"))&&cap.kind().equals(e.get("kind"))&&cap.connector().toString().equals(e.get("connector"))&&cap.entity().toString().equals(e.get("entity"))&&cap.fingerprint().equals(e.get("fingerprint"))&&e.get("revision") instanceof Number n&&n.longValue()==cap.revision()&&e.get("measures") instanceof Map<?,?> measures&&measures.get(field) instanceof Map<?,?> rule){String currency=dimension(row,rule,"currency"),unit=dimension(row,rule,"unit");if(!currency.matches("[A-Z]{3}|NONE")||!unit.matches("[A-Za-z0-9_/-]{1,24}"))throw new ChatFailure("CHAT_INCOMPATIBLE_MEASURES");return Map.of("currency",currency,"unit",unit);}throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");}
 private static String dimension(Map<?,?> row,Map<?,?> rule,String name){if(rule.containsKey(name+"Field")==rule.containsKey(name+"Literal"))throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");Object value=rule.containsKey(name+"Field")?row.get(rule.get(name+"Field")):rule.get(name+"Literal");if(!(value instanceof String s))throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");return s;}
 public Optional<String> identity(UUID org,ChatCapabilities.Capability cap){var matches=entries.stream().filter(e->org.toString().equals(e.get("organization"))&&cap.kind().equals(e.get("kind"))&&cap.connector().toString().equals(e.get("connector"))&&cap.entity().toString().equals(e.get("entity"))&&e.get("revision") instanceof Number n&&n.longValue()==cap.revision()&&cap.fingerprint().equals(e.get("fingerprint"))&&Boolean.TRUE.equals(e.get("verifiedReadOnly"))).toList();if(matches.size()!=1)return Optional.empty();Object value=matches.getFirst().get("canonicalSource");if(!(value instanceof String id)||!id.matches("[a-z][a-z0-9_-]{0,63}"))throw new ChatFailure("CHAT_BINDING_INVALID");return Optional.of(id);}
}
